_TINY_WPB = int(_os.environ.get("QR_TINY_WPB", "2"))


def _tiny_qr(A):
    B, n, _ = A.shape
    kern = _get_kernel()
    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
    # The kernel writes taub[k] for every k=0..n-1, so no pre-zeroing memset.
    tau = torch.empty((B, n), device=A.device, dtype=torch.float32)
    kern.launch_tiny(A.contiguous(), H, tau, B, n, _TINY_WPB)
    return H, tau


def _block_qr(A):
    B, n, _ = A.shape
    kern = _get_kernel()
    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
    tau = torch.zeros((B, n), device=A.device, dtype=torch.float32)
    nthreads = ((n + 31) // 32) * 32     # one thread per column, warp-rounded
    kern.launch_block(A.contiguous(), H, tau, B, n, nthreads)
    return H, tau


# Panel width / trailing chunk for the single-launch megakernel, by n. smem must
# hold n*NB (panel) + n*CT (trailing chunk) + small WY/T/red. Picked so the smem
# footprint fits the 228KB B200 opt-in cap.
def _mega_params(n):
    if n <= 512:
        return 32, 32, 256       # NB, CT, TPB
    elif n <= 1024:
