            tuple(data.shape),
            tuple(data.stride()),
            device=data.device,
            dtype=data.dtype,
        )
        work.copy_(data)
        tau = torch.empty(
            (int(data.shape[0]), int(data.shape[-1])),
            device=data.device,
            dtype=torch.float32,
        )
        for begin, end in _partition_bounds(int(data.shape[0]), parts):
